// The handful of shared assets gameplay code needs by name (glow material, effect materials, the sound
// library). They live in one ScriptableObject at Resources/MetalGameAssets, generated by the asset pipeline,
// so runtime code never hard-codes asset paths and the assets are always included in builds.
using System.Collections.Generic;
using UnityEngine;

namespace Metalization
{
    [CreateAssetMenu(menuName = "Metalization/Game Assets", fileName = "MetalGameAssets")]
    public class MetalGameAssets : ScriptableObject
    {
        [Tooltip("Unlit additive glow (consoles, lifts, pickups, projectiles, jet flames). Tinted per renderer.")]
        public Material glowMaterial;
        [Tooltip("Additive particle material for sparks, flashes and beams.")]
        public Material particleMaterial;
        [Tooltip("Alpha-blended particle material for smoke and dust.")]
        public Material smokeMaterial;
        [Tooltip("Additive material for line-renderer beams (tracers, laser sights, tethers, welding arcs).")]
        public Material beamMaterial;
        [Tooltip("See-through energy field.")]
        public Material energyFieldMaterial;
        [Tooltip("Portal window material (render texture).")]
        public Material portalMaterial;
        [Tooltip("Environment materials by short name (Floor, Wall, Dark, Hazard, Glow, Metal).")]
        public List<NamedMaterial> environment = new List<NamedMaterial>();
        public MetalSoundLibrary sounds;
        [Tooltip("The player's robot, used by game modes that don't name one.")]
        public MetalBotArchetype playerArchetype;
        [Tooltip("Pickup models: the wrench (repair kit) and the ammo crate.")]
        public GameObject wrenchModel;
        public GameObject ammoCrateModel;
        [Tooltip("Level Select list for the title and pause menus.")]
        public MetalLevelSettings levels;
        [Tooltip("Font used by the HUD and menus (null = Unity's default).")]
        public Font uiFont;

        [System.Serializable]
        public class NamedMaterial
        {
            public string name;
            public Material material;
        }

        static MetalGameAssets instance;
        static bool triedLoad;

        /// <summary>The shared asset registry, or null (with one warning) if the pipeline hasn't built it.</summary>
        public static MetalGameAssets Get()
        {
            if (instance == null && !triedLoad)
            {
                triedLoad = true;
                instance = Resources.Load<MetalGameAssets>("MetalGameAssets");
                if (instance == null)
                {
                    Debug.LogWarning("[Metal] Resources/MetalGameAssets not found - run Metalization > Build All Assets.");
                }
            }
            return instance;
        }

        public static Material Environment(string name)
        {
            MetalGameAssets a = Get();
            if (a == null) return null;
            foreach (NamedMaterial m in a.environment)
            {
                if (m.name == name) return m.material;
            }
            return null;
        }

        public static Material Glow => Get() != null ? Get().glowMaterial : null;
    }

    /// <summary>Material helpers shared by the procedural props.</summary>
    public static class MetalMaterials
    {
        static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");
        static readonly int ColorId = Shader.PropertyToID("_Color");
        static readonly int EmissionId = Shader.PropertyToID("_EmissionColor");

        /// <summary>Gives a renderer the shared glow material, tinted with an HDR colour (colour * intensity).</summary>
        public static void SetGlow(Renderer renderer, Color color, float intensity)
        {
            if (renderer == null) return;
            Material glow = MetalGameAssets.Glow;
            if (glow != null && renderer.sharedMaterial != glow)
            {
                renderer.sharedMaterial = glow;
            }
            SetGlowColor(renderer, color, intensity);
        }

        /// <summary>Retints a glow renderer without touching its material.</summary>
        public static void SetGlowColor(Renderer renderer, Color color, float intensity)
        {
            if (renderer == null) return;
            var block = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(block);
            Color hdr = new Color(color.r * intensity, color.g * intensity, color.b * intensity, color.a);
            block.SetColor(BaseColorId, hdr);
            block.SetColor(ColorId, hdr);
            block.SetColor(EmissionId, hdr);
            renderer.SetPropertyBlock(block);
        }

        /// <summary>A primitive shape (no collider) parented under parent, for procedural props and effects.</summary>
        public static GameObject Shape(PrimitiveType type, Transform parent, string name)
        {
            GameObject go = GameObject.CreatePrimitive(type);
            go.name = name;
            Object.Destroy(go.GetComponent<Collider>());
            go.transform.SetParent(parent, false);
            Renderer r = go.GetComponent<Renderer>();
            r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            return go;
        }
    }
}
